from typing import List, Union
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from pydantic import BaseModel, validator, ValidationError, root_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Union[str, int, float, Decimal]

    @validator('quantity')
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError('quantity must be >= 1')
        return v

    @validator('unit_price', pre=True)
    def unit_price_to_decimal(cls, v):
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError('unit_price must be a valid decimal number')
        if d < 0:
            raise ValueError('unit_price must be >= 0')
        return d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    def json_dict(self):
        return {
            'sku': self.sku,
            'quantity': self.quantity,
            'unit_price': f'{self.unit_price:.2f}',
        }


class Invoice(BaseModel):
    number: str
    issued_at: Union[str, datetime]
    lines: List[InvoiceLine]

    @validator('issued_at', pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError('issued_at must be ISO 8601 datetime string or datetime object')
        else:
            raise ValueError('issued_at must be ISO 8601 datetime string or datetime object')
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    @root_validator
    def check_lines_and_compute_total(cls, values):
        lines = values.get('lines')
        if not lines:
            raise ValueError('lines must be a non-empty list')
        total = Decimal('0.00')
        for line in lines:
            total += line.unit_price * line.quantity
        values['total'] = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return values

    def json_dict(self):
        return {
            'number': self.number,
            'issued_at': self.issued_at.strftime('%Y-%m-%dT%H:%M:%SZ'),
            'lines': [line.json_dict() for line in self.lines],
            'total': f'{self.total:.2f}',
        }


def export_invoice(data: dict) -> str:
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e
    import json
    return json.dumps(invoice.json_dict(), separators=(',', ':'))

